// Format structured error diagnostics
const errorData = $json.execution?.error || {};
const workflow = $json.workflow || {};
const execution = $json.execution || {};

const workflowName = workflow.name || 'Unknown Practice Workflow';
const executionId = execution.id || 'N/A';
const timestamp = new Date().toISOString();
const errorMessage = errorData.message || 'Unknown execution error occurred';
const nodeName = errorData.node?.name || 'Unknown Node';

const alertPayload = {
  severity: 'CRITICAL',
  workflow_name: workflowName,
  execution_id: executionId,
  node: nodeName,
  error_message: errorMessage,
  timestamp,
  alert_message: `🚨 [AUREVIA ERROR ALERT]\nWorkflow: ${workflowName}\nNode: ${nodeName}\nExecution: ${executionId}\nError: ${errorMessage}\nTimestamp: ${timestamp}\nAction Required: Check n8n execution log immediately.`
};

return [{ json: alertPayload }];
